    /** Poll the Host proxy until one uploaded file finishes server-side processing. */
    async function waitFileReady(id, timeoutMs = 60000) {
      const started = Date.now()
      for (;;) {
        const data = await api(`/file/status?ids=${encodeURIComponent(id)}`)
        const file = (data.files ?? []).find(entry => entry.id === id)
        if (file !== undefined && file.status === 'SUCCESS') return file
        if (file !== undefined && (file.status === 'FAILED' || file.status === 'REJECTED')) {
          throw new Error(`文件处理失败（${file.status}）`)
        }
        if (Date.now() - started > timeoutMs) throw new Error('文件处理超时，请在网页版重试')
        await new Promise(resolve => { setTimeout(resolve, 1500) })
      }
    }

    /** Mirrors chat.deepseek.com: up to 100MB per file, up to 50 files per send. */
    const MAX_UPLOAD_BYTES = 100 * 1024 * 1024
    const MAX_UPLOAD_FILES = 50
    /** Extensions we can show read-only in the DSH right sidebar. */
    const TEXT_EXTENSIONS = [
      'txt', 'md', 'markdown', 'json', 'jsonl', 'csv', 'tsv', 'log', 'yaml', 'yml', 'toml', 'ini', 'conf',
      'xml', 'html', 'htm', 'css', 'js', 'mjs', 'cjs', 'ts', 'tsx', 'jsx', 'py', 'rb', 'go', 'rs', 'java',
      'c', 'h', 'cpp', 'hpp', 'cs', 'php', 'sh', 'bash', 'zsh', 'ps1', 'sql', 'tex', 'r', 'kt', 'swift', 'srt', 'vtt',
    ]
