    function extensionOf(name) {
      const dot = String(name ?? '').lastIndexOf('.')
      return dot < 0 ? '' : String(name).slice(dot + 1).toLowerCase()
    }

    function isTextFile(name) {
      return TEXT_EXTENSIONS.includes(extensionOf(name))
    }

    /** Word documents: unzip word/document.xml and strip the tags. */
    function isDocxFile(name) {
      return extensionOf(name) === 'docx'
    }

    /** How the reader lays one attachment out: Markdown blocks, or plain text. */
    function previewFormat(name) {
      const ext = extensionOf(name)
      if (ext === 'md' || ext === 'markdown' || ext === 'mdx' || ext === 'docx') return 'markdown'
      return 'text'
    }

    /** Everything we can render read-only in the right sidebar. */
    function isPreviewable(name) {
      return isTextFile(name) || isDocxFile(name)
    }

    /** Read the central directory of a zip blob and inflate word/document.xml. */
    async function extractDocxText(file) {
      const bytes = new Uint8Array(await file.arrayBuffer())
      const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength)
      const u16 = at => view.getUint16(at, true)
      const u32 = at => view.getUint32(at, true)
      let eocd = -1
      for (let at = bytes.length - 22; at >= 0 && at > bytes.length - 66_000; at -= 1) {
        if (u32(at) === 0x06054b50) { eocd = at; break }
      }
      if (eocd < 0) return ''
      let cursor = u32(eocd + 16)
      const count = u16(eocd + 10)
      const decoder = new TextDecoder()
      for (let index = 0; index < count; index += 1) {
        if (u32(cursor) !== 0x02014b50) break
        const method = u16(cursor + 10)
        const compressedSize = u32(cursor + 20)
        const nameLength = u16(cursor + 28)
        const extraLength = u16(cursor + 30)
        const commentLength = u16(cursor + 32)
        const localOffset = u32(cursor + 42)
        const name = decoder.decode(bytes.subarray(cursor + 46, cursor + 46 + nameLength))
        cursor += 46 + nameLength + extraLength + commentLength
        if (name !== 'word/document.xml') continue
        const localNameLength = u16(localOffset + 26)
        const localExtraLength = u16(localOffset + 28)
        const start = localOffset + 30 + localNameLength + localExtraLength
        const data = bytes.subarray(start, start + compressedSize)
        const plain = method === 0
          ? data
          : new Uint8Array(await new Response(
              new Blob([data]).stream().pipeThrough(new DecompressionStream('deflate-raw')),
            ).arrayBuffer())
        return docxToMarkdown(decoder.decode(plain))
      }
      return ''
    }

    /** Decode the five XML entities Word actually emits. */
    function decodeXml(value) {
      return value
        .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"')
        .replace(/&apos;/g, "'").replace(/&amp;/g, '&')
    }

    /** Word heading styles, in order; anything else becomes body text. */
    const DOCX_HEADINGS = { Heading1: 1, Heading2: 2, Heading3: 3, Heading4: 4, Heading5: 5, Heading6: 6 }

    /**
     * Turn word/document.xml into Markdown so the reader can lay it out
     * instead of dumping one flat blob: paragraph styles become headings,
     * list paragraphs become bullets, and bold/italic runs keep emphasis.
     */
    function docxToMarkdown(xml) {
      const body = xml.replace(/<\?xml[^>]*\?>/g, '')
      const blocks = []
      const paragraphs = body.match(/<w:p\b[\s\S]*?<\/w:p>/g) ?? []
      for (const paragraph of paragraphs) {
        const style = /<w:pStyle\s+w:val="([^"]+)"/.exec(paragraph)?.[1] ?? ''
        // Word's own outline level is the reliable heading signal: most
        // documents shop out of Word carry outlineLvl rather than named styles.
        const outline = /<w:outlineLvl\s+w:val="(\d)"/.exec(paragraph)?.[1]
        const numbered = /<w:numPr>/.test(paragraph)
        const runs = []
        const runMatches = paragraph.match(/<w:r\b[\s\S]*?<\/w:r>/g) ?? []
        for (const run of runMatches) {
          const bold = /<w:b\s*\/>|<w:b\s+w:val="(?:1|true)"/.test(run)
          const italic = /<w:i\s*\/>|<w:i\s+w:val="(?:1|true)"/.test(run)
          const pieces = []
          const tokenPattern = /<w:t\b[^>]*>([\s\S]*?)<\/w:t>|<w:tab\/>|<w:br\/>/g
          let token = tokenPattern.exec(run)
          while (token !== null) {
            if (token[1] !== undefined) pieces.push(decodeXml(token[1]))
            else if (token[0] === '<w:tab/>') pieces.push(' ')
            else pieces.push('\n')
            token = tokenPattern.exec(run)
          }
          let text = pieces.join('')
          if (text === '') continue
          if (bold) text = '**' + text + '**'
          if (italic) text = '*' + text + '*'
          runs.push(text)
        }
        const text = runs.join('').replace(/\n{3,}/g, '\n\n').trim()
        if (text === '') continue
        const level = DOCX_HEADINGS[style] ?? (outline === undefined ? undefined : Math.min(Number(outline) + 1, 6))
        // Headings are bold through CSS already; drop the markers Word put there.
        if (level !== undefined) blocks.push('#'.repeat(level) + ' ' + text.replace(/\*\*/g, '').replace(/\*/g, ''))
        else if (numbered || /^(ListParagraph|ListBullet\d?)$/.test(style)) blocks.push('- ' + text)
        else blocks.push(text)
      }
      if (blocks.length > 0) return blocks.join('\n\n')
      return decodeXml(body.replace(/<[^>]+>/g, '')).trim()
    }

    function readPreviewMap() {
      try {
        const raw = localStorage.getItem(PREVIEW_MAP_KEY)
        const value = raw === null ? null : JSON.parse(raw)
        return value !== null && typeof value === 'object' ? value : {}
      } catch { return {} }
    }

    function writePreviewMap(next) {
      try { localStorage.setItem(PREVIEW_MAP_KEY, JSON.stringify(next)) } catch { /* full or blocked */ }
    }

    /** Remember the side-panel URL for one attachment, keyed by its display name. */
    function rememberPreview(name, url) {
      const map = readPreviewMap()
      map[name] = url
      writePreviewMap(map)
    }

    /**
     * Open one attachment read-only in the right sidebar. Falls back to
     * registering the text on the Host when only the name is left (for
     * example after the message list was refetched from chat.deepseek.com).
     */
    async function openAttachmentPreview(name, text) {
      const saved = readPreviewMap()[name]
      if (typeof saved === 'string' && saved !== '') { void openTextPreview(name, saved); return }
      const body = typeof text === 'string' ? text : ''
      if (body !== '') {
        try {
          const posted = await api('/file/preview', { method: 'POST', body: { name, text: body } })
          rememberPreview(name, posted.url)
          void openTextPreview(name, posted.url)
          return
        } catch (error) { console.warn('[chat-switch] preview register failed:', error) }
      }
      store.set({ error: `「${name}」的预览缓存已失效，请重新上传该文件后再点` })
    }

    /** Open a read-only text preview in the DSH right sidebar. */
    /**
     * Read-only attachment reader. It renders inside the Chat surface rather
     * than delegating to the session-scoped right sidebar: the sidebar is only
     * addressable while a DSH session owns the panel, so in Chat mode a tab
     * request could resolve to nothing at all.
     */
    async function openTextPreview(name, url) {
      const absolute = String(url).startsWith('http') ? String(url) : `${window.location.origin}${url}`
      store.set({ docPreview: { name, url: absolute, text: '', error: '', loading: true } })
      try {
        const response = await fetch(absolute, { credentials: 'same-origin', cache: 'no-store' })
        const text = await response.text()
        if (!response.ok) throw new Error(text.slice(0, 200) || `HTTP ${response.status}`)
        // set() with a function REPLACES the whole snapshot, so every branch
        // has to carry ...state or the store loses mode/messages.
        store.set(state => (state.docPreview?.url === absolute
          ? { ...state, docPreview: { ...state.docPreview, text, loading: false } }
          : state))
      } catch (error) {
        store.set(state => (state.docPreview?.url === absolute
          ? { ...state, docPreview: { ...state.docPreview, loading: false, error: String(error?.message ?? error) } }
          : state))
      }
    }

    async function uploadFiles(fileList) {
      const files = Array.from(fileList ?? [])
      if (files.length === 0) return
      if (files.length > MAX_UPLOAD_FILES) {
        store.set({ error: `一次最多上传 ${MAX_UPLOAD_FILES} 个文件（本次 ${files.length} 个）` })
        return
      }
      const oversized = files.find(file => file.size > MAX_UPLOAD_BYTES)
      if (oversized !== undefined) {
        store.set({ error: `${oversized.name} 超过单文件上限 100MB` })
        return
      }
      store.set({ uploading: true, error: null, uploadStage: { index: 0, total: files.length, stage: 'start', name: '' } })
      /** PoW is the slow part (~10–20 s); solving the next one during the
       *  current upload keeps multi-file drops from paying it serially. */
      const solveChallenge = async () => {
        const challenge = await api('/pow/challenge', { method: 'POST', body: { targetPath: '/api/v0/file/upload_file' } })
        return { challenge, answer: await solvePow(challenge) }
      }
      let prepared = solveChallenge()
      try {
        for (const [fileIndex, file] of files.entries()) {
          const report = stage => { store.set({ uploadStage: { index: fileIndex + 1, total: files.length, stage, name: file.name } }) }
          report('reading')
          const bytes = new Uint8Array(await file.arrayBuffer())
          let binary = ''
          for (let i = 0; i < bytes.length; i += 0x8000) {
            binary += String.fromCharCode.apply(null, bytes.subarray(i, i + 0x8000))
          }
          report('pow')
          const { challenge, answer } = await prepared
          prepared = fileIndex + 1 < files.length ? solveChallenge() : null
          report('uploading')
          const uploaded = await api('/file/upload', {
            method: 'POST',
            body: {
              name: file.name,
              type: file.type || 'application/octet-stream',
              dataBase64: btoa(binary),
              powHeader: powHeader(challenge, answer),
            },
          })
          const preview = typeof file.type === 'string' && file.type.startsWith('image/')
            ? URL.createObjectURL(file)
            : null
          report('processing')
          const ready = await waitFileReady(uploaded.id)
          let body = ''
          if (isPreviewable(uploaded.name) && file.size <= 8 * 1024 * 1024) {
            try {
              body = isDocxFile(uploaded.name) ? await extractDocxText(file) : await file.text()
              const saved = await api('/file/preview', { method: 'POST', body: { name: uploaded.name, text: body } })
              rememberPreview(uploaded.name, saved.url)
            } catch (error) {
              body = ''
              console.warn('[chat-switch] preview cache failed:', error)
            }
          }
          store.set(state => ({
            ...state,
            attachments: [...state.attachments, {
              id: uploaded.id,
              name: uploaded.name,
              preview,
              size: file.size,
              isImage: preview !== null,
              signedPath: ready.signedPath ?? '',
              text: body,
            }],
          }))
        }
      } catch (error) {
        store.set({ error: `上传失败：${String(error?.message ?? error)}` })
      } finally {
        store.set({ uploading: false, uploadStage: null })
      }
    }

    function renameSession(session) {
      requestConfirm({
        title: '重命名对话',
        confirmLabel: '保存',
        input: session.title ?? '',
        action: (value) => {
          const title = String(value ?? '').trim()
          if (title === '') return
          void (async () => {
            try {
              await api('/session/title', { method: 'POST', body: { sessionId: session.id, title } })
              await loadSessions()
            } catch (error) {
              store.set({ error: `重命名失败：${String(error?.message ?? error)}` })
            }
          })()
        },
      })
    }

    async function setPinned(session, pinned) {
      try {
        await api('/session/pinned', { method: 'POST', body: { sessionId: session.id, pinned } })
        await loadSessions()
      } catch (error) {
        store.set({ error: `置顶失败：${String(error?.message ?? error)}` })
      }
    }

    async function removeSessions(ids) {
      if (ids.length === 0) return
      try {
        for (const id of ids) await api('/session/delete', { method: 'POST', body: { sessionId: id } })
        const state = store.get()
        if (state.activeId !== null && ids.includes(state.activeId)) store.set({ activeId: null, messages: [] })
        store.set({ selected: [] })
        await loadSessions()
      } catch (error) {
        store.set({ error: `删除失败：${String(error?.message ?? error)}` })
      }
    }

    /** ArkWeb blocks window.confirm, so every destructive action goes through this. */
    function requestConfirm(request) {
      store.set({ confirmRequest: request })
    }

    function closeConfirm() {
      store.set({ confirmRequest: null })
    }

    async function setPinnedMany(items, pinned) {
      for (const item of items) {
        await api('/session/pinned', { method: 'POST', body: { sessionId: item.id, pinned } })
      }
      store.set({ selected: [], manageMode: false })
      await loadSessions()
    }

    /** Group rows the way the DeepSeek app does: pinned first, then by recency. */
    function groupSessions(items) {
      const groups = []
      const pinned = items.filter(item => item.pinned)
      const rest = items.filter(item => !item.pinned)
      if (pinned.length > 0) groups.push({ label: '置顶', items: pinned })
      const now = new Date()
      const dayStart = new Date(now.getFullYear(), now.getMonth(), now.getDate()).getTime()
      const buckets = []
      const byLabel = new Map()
      for (const item of rest) {
        const raw = Number(item.updatedAt ?? 0)
        const ms = raw > 1e12 ? raw : raw * 1000
        let label
        if (ms >= dayStart) label = '今天'
        else if (ms >= dayStart - 6 * 86400000) label = '7 天内'
        else if (ms >= dayStart - 29 * 86400000) label = '30 天内'
        else {
          const date = new Date(ms)
          label = `${date.getFullYear()}年${date.getMonth() + 1}月`
        }
        if (!byLabel.has(label)) { byLabel.set(label, []); buckets.push({ label, items: byLabel.get(label) }) }
        byLabel.get(label).push(item)
      }
      for (const bucket of buckets) groups.push(bucket)
      return groups
    }

    function toggleSelected(id) {
      store.set(state => ({
        ...state,
        selected: state.selected.includes(id) ? state.selected.filter(item => item !== id) : [...state.selected, id],
      }))
    }

    /** Fold the drawer only when it is currently open; never toggle blind. */
    function closeDrawerIfOpen() {
      const frame = document.querySelector('[data-sidebar-drawer]')
      if (frame === null) return
      // AppFrame marks the collapsed frame with data-sidebar-collapsed.
      if (frame.getAttribute('data-sidebar-collapsed') === 'true') return
      try { ctxRef.ctx?.get?.('layout')?.toggleSidebar?.() } catch { /* layout not ready */ }
    }

    async function startNewChat(fromSidebar) {
      try {
        focusChatPanel()
        store.set({ error: null })
        const data = await api('/session/create', { method: 'POST', body: {} })
        const session = data.session
        // The click handler already folded the drawer; never toggle here, or a
        // second toggle re-opens it right after the shell closed it.
        store.set(state => ({
          ...state,
          activeId: session.id,
          messages: [],
          streamText: '',
          streamThinking: '',
          sessions: [session, ...state.sessions.filter(item => item.id !== session.id)],
        }))
        return session
      } catch (error) {
        store.set({ error: String(error?.message ?? error) })
        return null
      }
    }

    async function sendMessage(job) {
      const state = store.get()
      const prompt = String(job === undefined ? state.draft : job.prompt).trim()
      if (prompt === '' || state.sending) return
      const outgoing = job === undefined ? state.attachments : []
      let sessionId = state.activeId
      if (sessionId === null) {
        const created = await startNewChat()
        if (created === null) return
        sessionId = created.id
      }
      const notReady = outgoing.filter(item => item.isImage === undefined)
      if (notReady.length > 0) {
        store.set({ error: '有附件还在处理中，稍等片刻再发送' })
        return
      }
      const thinking = state.thinkingOn
      const search = state.searchOn
      lastFragmentType = 'RESPONSE'
      store.set(prev => ({
        streamThinkMs: 0,
        streamDone: false,
        ...prev,
        draft: job === undefined ? '' : prev.draft,
        attachments: job === undefined ? [] : prev.attachments,
        sending: true,
        powStage: 'challenge',
        streamText: '',
        streamThinking: '',
        streamSources: [],
        messages: job === undefined
          ? [...prev.messages, {
              id: `local-${Date.now()}`,
              role: 'user',
              text: prompt,
              thinking: '',
              files: prev.attachments.map(item => item.name),
              attachments: prev.attachments.map(item => ({ name: item.name, preview: item.preview, isImage: item.isImage })),
            }]
          : prev.messages.filter(item => item.id !== job.dropId),
        thinkingStartAt: Date.now(),
        thinkingMs: 0,
      }))
      try {
        const challenge = await api('/pow/challenge', { method: 'POST', body: { targetPath: '/api/v0/chat/completion' } })
        store.set({ powStage: 'solving' })
        const answer = await solvePow(challenge)
        store.set({ powStage: 'streaming' })
        await streamCompletion({
          sessionId, prompt, thinking, search,
          powHeader: powHeader(challenge, answer),
          refFileIds: outgoing.map(item => item.id),
        })
        store.set({ thinkingMs: store.get().thinkingStartAt === 0 ? 0 : Date.now() - store.get().thinkingStartAt })
        const finished = store.get()
        if (finished.streamText !== '' || finished.streamThinking !== '') {
          store.set(prev => ({
            ...prev,
            messages: [...prev.messages, {
              id: `local-a-${Date.now()}`,
              role: 'assistant',
              text: finished.streamText,
              thinking: finished.streamThinking,
              thinkMs: prev.streamThinkMs > 0
                ? prev.streamThinkMs
                : (prev.thinkingStartAt === 0 ? 0 : Date.now() - prev.thinkingStartAt),
            }],
            streamText: '',
            streamThinking: '',
          }))
        }
        void loadSessions()
      } catch (error) {
        if (String(error?.name ?? '') !== 'AbortError') {
          store.set({ error: `发送失败：${String(error?.message ?? error)}` })
        }
      } finally {
        store.set({ sending: false, powStage: 'idle' })
        streamController = undefined
      }
    }

    async function saveToken(token) {
      store.set({ working: true, error: null })
      try {
        const data = await api('/token', { method: 'POST', body: { token: extractToken(token) } })
        store.set(state => ({ ...state, working: false, tokenDraft: '', status: { ...(state.status ?? {}), signedIn: true, user: data.user } }))
        await loadSessions()
      } catch (error) {
        store.set({ working: false, error: String(error?.message ?? error) })
      }
    }

    async function signOut() {
      store.set({ working: true })
      try {
        await api('/logout', { method: 'POST', body: {} })
        store.set({ working: false, sessions: [], messages: [], activeId: null, status: { ...(store.get().status ?? {}), signedIn: false, user: null } })
      } catch (error) {
        store.set({ working: false, error: String(error?.message ?? error) })
      }
    }

    // ------------------------------------------------------------ mode glue

    function readStoredFlag(key, fallback) {
      try {
        const value = window.localStorage.getItem(key)
        return value === null ? fallback : value === 'true'
      } catch { return fallback }
    }

    function writeStoredFlag(key, value) {
      try { window.localStorage.setItem(key, String(value)) } catch { /* private mode */ }
    }

    function readStoredMode() {
      try {
        const value = window.localStorage.getItem(MODE_KEY)
        return value === 'chat' ? 'chat' : 'harness'
      } catch { return 'harness' }
    }

    function applyMode(mode) {
      try { window.localStorage.setItem(MODE_KEY, mode) } catch { /* private mode */ }
      store.set({ mode })
      const layout = ctxRef.layout
      if (layout === undefined || layout === null) return
      try {
        if (mode === 'chat') layout.selectPanel('chat')
        else layout.selectPanel(null)
      } catch (error) {
        console.warn('[chat-switch] selectPanel failed:', error)
      }
    }

    /** The client root context, captured by apply() for the components below. */
    const ctxRef = { ctx: null, get layout() { return this.ctx?.get?.('layout') ?? undefined } }

