    function ConfirmDialog() {
      const request = useStore(state => state.confirmRequest)
      const [value, setValue] = useState('')
      if (request === null || request === undefined) return null
      const needsInput = typeof request.input === 'string'
      const current = needsInput && value === '' ? request.input : value
      const layer = h('div', { style: DLG.mask, onClick: () => { closeConfirm() } },
        h('div', { style: DLG.card, onClick: event => { event.stopPropagation() } },
          h('div', { style: DLG.title }, request.title),
          request.message === undefined ? null : h('div', { style: DLG.text }, request.message),
          needsInput ? h('input', {
            style: DLG.input,
            value: current,
            autoFocus: true,
            onChange: event => { setValue(event.target.value) },
          }) : null,
          h('div', { style: DLG.actions },
            h('button', { style: DLG.cancel, type: 'button', onClick: () => { closeConfirm() } }, '取消'),
            h('button', {
              style: request.danger === true ? DLG.danger : DLG.confirm,
              type: 'button',
              onClick: () => {
                closeConfirm()
                void request.action?.(needsInput ? (value === '' ? request.input : value) : undefined)
              },
            }, request.confirmLabel ?? '确定'))))
      if (typeof reactDom?.createPortal === 'function' && typeof document !== 'undefined' && document.body !== null) {
        return reactDom.createPortal(layer, document.body)
      }
      return layer
    }

