    /** Transient pill at the bottom of the chat surface: "已复制" and friends. */
    let toastTimer = 0
    function flash(text) {
      store.set({ toast: text })
      if (toastTimer !== 0) clearTimeout(toastTimer)
      toastTimer = setTimeout(() => { toastTimer = 0; store.set({ toast: '' }) }, 1600)
    }

    async function copyText(text) {
      try {
        await navigator.clipboard.writeText(text)
        return true
      } catch {
        try {
          const area = document.createElement('textarea')
          area.value = text
          area.style.position = 'fixed'
          area.style.opacity = '0'
          document.body.appendChild(area)
          area.select()
          const ok = document.execCommand === undefined ? false : document.execCommand('copy')
          document.body.removeChild(area)
          return ok === true
        } catch { return false }
      }
    }

    async function copyAnswer(message) {
      const ok = await copyText(message.text)
      flash(ok ? '已复制' : '复制失败，请手动选择文本')
    }

    /** Re-ask the same prompt: the answer for this row is dropped first. */
    async function regenerateAnswer(message) {
      const state = store.get()
      if (state.sending) return
      const index = state.messages.findIndex(item => item.id === message.id)
      if (index < 0) return
      let userIndex = index - 1
      while (userIndex >= 0 && state.messages[userIndex].role !== 'user') userIndex -= 1
      if (userIndex < 0) return
      const prompt = String(state.messages[userIndex].text ?? '').trim()
      if (prompt === '') return
      const files = Array.isArray(state.messages[userIndex].files) ? state.messages[userIndex].files : []
      await sendMessage({ prompt, files, dropId: message.id })
    }

    /** Say the answer out loud with the browser's own speech engine. */
    function speakAnswer(message) {
      const synth = typeof window !== 'undefined' ? window.speechSynthesis : undefined
      if (synth === undefined) { flash('当前环境不支持朗读'); return }
      if (store.get().speakingId === message.id) {
        synth.cancel()
        store.set({ speakingId: '' })
        return
      }
      synth.cancel()
      const plain = String(message.text ?? '').replace(/[#*`>]/g, '')
      const utter = new SpeechSynthesisUtterance(plain)
      utter.lang = 'zh-CN'
      utter.onend = () => { store.set({ speakingId: '' }) }
      utter.onerror = () => { store.set({ speakingId: '' }) }
      store.set({ speakingId: message.id })
      synth.speak(utter)
    }

    async function shareAnswer(message) {
      const state = store.get()
      const link = state.activeId === null ? '' : `https://chat.deepseek.com/a/chat/s/${state.activeId}`
      const ok = link === '' ? await copyText(message.text) : await copyText(link)
      flash(ok ? (link === '' ? '已复制回答' : '已复制会话链接') : '分享失败')
    }

    /** The web client's answer toolbar, one glyph per action. */
    function MessageActions({ message }) {
      const state = store.get()
      const speaking = state.speakingId === message.id
      const buttons = [
        { key: 'copy', icon: 'copy', title: '复制', run: () => { void copyAnswer(message) } },
        { key: 'redo', icon: 'refresh', title: '重新生成', run: () => { void regenerateAnswer(message) } },
        { key: 'speak', icon: speaking ? 'pause' : 'play', title: speaking ? '停止朗读' : '朗读', on: speaking, run: () => { speakAnswer(message) } },
        { key: 'share', icon: 'share', title: '分享', run: () => { void shareAnswer(message) } },
      ]
      return h('div', { className: 'csx-actions' }, buttons.map(item => h('button', {
        key: item.key,
        type: 'button',
        className: 'csx-act',
        title: item.title,
        'aria-label': item.title,
        'data-on': item.on === true ? 'true' : undefined,
        onClick: event => { event.stopPropagation(); item.run() },
      }, h(Icon, { name: item.icon }))))
    }

